\set ON_ERROR_STOP on
BEGIN;
WITH tenant AS(SELECT id organisation_id FROM "Organisation" WHERE slug='meadow-view-home-care'),actor AS(SELECT id user_id FROM "User" WHERE email='e2e-rm@release-gate.invalid'),definition AS(SELECT id definition_id FROM "RegisterDefinition" WHERE key='safeguarding' AND "organisationId" IS NULL),location AS(SELECT id location_id FROM "ServiceLocation" WHERE code='GUILDFORD' AND "organisationId"=(SELECT organisation_id FROM tenant))
INSERT INTO "RegisterEntry"(id,"organisationId","definitionId","locationId",reference,"eventDate",title,summary,"riskLevel",status,"ownerId",data,"createdById","updatedAt") SELECT (substr(md5('safeguarding-performance-'||s),1,8)||'-'||substr(md5('safeguarding-performance-'||s),9,4)||'-4'||substr(md5('safeguarding-performance-'||s),14,3)||'-8'||substr(md5('safeguarding-performance-'||s),18,3)||'-'||substr(md5('safeguarding-performance-'||s),21,12))::uuid,tenant.organisation_id,definition.definition_id,location.location_id,'PERF-SG-'||lpad(s::text,5,'0'),CURRENT_TIMESTAMP-(s||' minutes')::interval,'Synthetic safeguarding probe '||s,'Disposable probe.','HIGH','IN_REVIEW',actor.user_id,'{}',actor.user_id,CURRENT_TIMESTAMP FROM generate_series(1,5000)s CROSS JOIN tenant CROSS JOIN actor CROSS JOIN definition CROSS JOIN location;
INSERT INTO "SafeguardingCase"(id,"organisationId","locationId","safeguardingId",status,"safetyPosition","concernCategories","triageRationale","referralDecision","externalResponseDueAt","investigatorId","updatedAt") SELECT gen_random_uuid(),e."organisationId",e."locationId",e.id,'AWAITING_EXTERNAL_RESPONSE','CONTROLLED_IMMEDIATE_RISK',ARRAY['Neglect / acts of omission'],'Synthetic triage.','MADE',CURRENT_TIMESTAMP-interval '2 days',e."ownerId",CURRENT_TIMESTAMP FROM "RegisterEntry"e WHERE e.reference LIKE 'PERF-SG-%';
EXPLAIN(ANALYZE,BUFFERS,FORMAT TEXT) SELECT count(*) FROM "SafeguardingCase" WHERE "organisationId"=(SELECT id FROM "Organisation" WHERE slug='meadow-view-home-care') AND "externalResponseDueAt"<CURRENT_TIMESTAMP;
ROLLBACK;
